/** Look up one image in a theme by slug (feature rows / spot placements). */
export function themeImage(theme: ThemeSlug, slug: string): ThemeImage {
  const found = themeMedia[theme].find((i) => i.slug === slug);
  if (!found) throw new Error(`Unknown theme image: ${theme}/${slug}`);
  return found;
}
